from commun import Corpus
PE = "Pease, Theodore C. et Raymond C. Werner (éd.) (1934), The French Foundations, 1680-1693, Collections of the Illinois State Historical Library, vol. XXIII"
C = Corpus('Recherches', 'PE34', PE, page_fmt='p. {}')
F = C.F
F('01', "Fort Saint-Louis du Rocher : fief concédé par La Salle à Jacques Bourdon d'Autray et à ses quatre associés (26 avril 1683)", 'etablissement', '1683-04-26', -88.985, 41.322, 'a', ["Jacques Bourdon d'Autray", 'Nicolas Doyon', "Pierre Prud'homme", 'André Hunault', 'Jean Filastreau', 'Cavelier de La Salle'],
  "En reconnaissance de ses services dans la découverte de la Louisiane et la construction du fort Saint-Louis, l'acte, conservé à la Chicago Historical Society, concède à d'Autray en fief et seigneurie cent vingt-six arpents de front sur la rive sud de la rivière des Illinois, à partir du ruisseau où La Salle a hiverné, avec l'île située au milieu de la rivière au-dessus du grand Rocher, sur quarante-deux arpents de profondeur ; droits de chasse et de pêche, foi et hommage au fort Saint-Louis et cens payable à la Saint-Louis selon la coutume de Paris. D'Autray reçoit aussi un emplacement de vingt pieds carrés dans le fort pour y bâtir une maison, à reprendre si le fort est déplacé, et doit traiter avec les Indiens au fort même. L'acte nomme ses quatre associés : l'armurier Nicolas Doyon, l'armurier Pierre Prud'homme (le chasseur égaré du fort Prud'homme), André Hunault et Jean Filastreau. Les éditeurs signalent aussi une concession de quarante-quatre arpents en fief à Prud'homme (11 août 1683), déposée chez le notaire Adhémar en 1717.",
  '19-27', "Les éditeurs identifient le ruisseau au Clayton Run (probable). D'Autray, au service de La Salle depuis 1675, sera tué par des Iroquois en 1688. Point au Starved Rock.")
F('02', "Fort Saint-Louis du Rocher : les premiers « habitants » et la concession de Michel Disy (1682-1683)", 'etablissement', '1682-12-01/1683-12-02', -88.990, 41.318, 'a', ['Michel Disy', 'Charles Disy', 'Laurriet', 'Brossard', 'chevalier de Baugy', 'Cavelier de La Salle'],
  "Dans un acte daté du 2 décembre 1683 (minutier Adhémar, Montréal), La Salle, se disant seigneur et gouverneur du fort Saint-Louis de la Louisiane, rappelle qu'il a attiré près du fort plusieurs villages indiens et qu'il a accordé des terres à des habitants français avec liberté de traite ; il concède à Michel Disy deux cents arpents, en réduisant le cens à un denier par an pour ceux qui ont demandé les premiers des habitations (décision prise à la rivière des Miamis le 1er décembre 1682). Disy fait ensuite déposer l'acte chez le notaire de Champlain, où il deviendra juge ; une concession identique à son frère Charles est conservée à Chicago. Une lettre de La Salle adressée « à Messieurs Laurriet et Brossard et tous les autres habitants » du fort leur recommande d'obéir au chevalier de Baugy, envoyé par La Barre pour prendre le poste.",
  '40-45', "Position approximative du fort.")
fiches = C.fiches
